import{_ as t,a0 as o,w as d,s as r,ao as l,I as p,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"用 Apache 服務器模組保護您的網站免受應用層 DOS 攻擊 | LCTT x X-CMD","titleTemplate":false,"description":"用 Apache 服務器模組保護您的網站免受應用層 DOS 攻擊 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Apache 服務器模組保護您的網站免受應用層 DOS 攻擊 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Apache 服務器模組保護您的網站免受應用層 DOS 攻擊 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171127 Protecting Your Website From Application Layer DOS Attacks With mod","title":"用 Apache 服務器模組保護您的網站免受應用層 DOS 攻擊","tag":"201802","desc":""},"relativePath":"201802/20171127 Protecting Your Website From Application Layer DOS Attacks With mod.md","filePath":"[post].md"}'),h={name:"201802/20171127 Protecting Your Website From Application Layer DOS Attacks With mod.md"};function c(g,s,u,b,k,v){const e=o("Link");return d(),r("div",null,[s[23]||(s[23]=l('<h1 id="用-apache-服務器模組保護您的網站免受應用層-dos-攻擊" tabindex="-1">用 Apache 服務器模組保護您的網站免受應用層 DOS 攻擊 <a class="header-anchor" href="#用-apache-服務器模組保護您的網站免受應用層-dos-攻擊" aria-label="Permalink to “用 Apache 服務器模組保護您的網站免受應用層 DOS 攻擊”">​</a></h1><p>有多種可以導致網站下線的攻擊方法，比較複雜的方法要涉及資料庫和編程方面的技術知識。一個更簡單的方法被稱為“<ruby>拒絕服務<rt>Denial Of Service</rt></ruby>”（DOS）攻擊。這個攻擊方法的名字來源於它的意圖：使普通客户或網站訪問者的正常服務請求被拒絕。</p><p>一般來説，有兩種形式的 DOS 攻擊：</p><ol><li>OSI 模型的三、四層，即網絡層攻擊</li><li>OSI 模型的七層，即應用層攻擊</li></ol><p>第一種類型的 DOS 攻擊——網絡層，發生於當大量的垃圾流量流向網頁服務器時。當垃圾流量超過網絡的處理能力時，網站就會宕機。</p><p>第二種類型的 DOS 攻擊是在應用層，是利用合法的服務請求，而不是垃圾流量。當頁面請求數量超過網頁服務器能承受的容量時，即使是合法訪問者也將無法使用該網站。</p><p>本文將着眼於緩解應用層攻擊，因為減輕網絡層攻擊需要大量的可用帶寬和上游提供商的合作，這通常不是通過配置網絡服務器就可以做到的。</p>',7)),p("p",null,[s[2]||(s[2]=a("通過配置普通的網頁服務器，可以保護網頁免受應用層攻擊，至少是適度的防護。防止這種形式的攻擊是非常重要的，因為 ",-1)),i(e,{href:"https://www.cloudflare.com"},{default:n(()=>[...s[0]||(s[0]=[a("Cloudflare",-1)])]),_:1}),s[3]||(s[3]=a(" 最近 ",-1)),i(e,{href:"https://blog.cloudflare.com/the-new-ddos-landscape/"},{default:n(()=>[...s[1]||(s[1]=[a("報告稱",-1)])]),_:1}),s[4]||(s[4]=a(" 網絡層攻擊的數量正在減少，而應用層攻擊的數量則在增加。",-1))]),p("p",null,[s[7]||(s[7]=a("本文將介紹如何使用 ",-1)),i(e,{href:"https://www.zdziarski.com/blog/"},{default:n(()=>[...s[5]||(s[5]=[a("zdziarski",-1)])]),_:1}),s[8]||(s[8]=a(" 開發的 Apache2 的模組 ",-1)),i(e,{href:"https://github.com/jzdziarski/mod_evasive"},{default:n(()=>[...s[6]||(s[6]=[a("mod_evasive",-1)])]),_:1}),s[9]||(s[9]=a("。",-1))]),s[24]||(s[24]=l(`<p>另外，mod_evasive 會阻止攻擊者通過嘗試數百個用户名和密碼的組合來進行猜測（即暴力攻擊）的企圖。</p><p>mod_evasive 會記錄來自每個 IP 地址的請求的數量。當這個數字超過相應 IP 地址的幾個閾值之一時，會出現一個錯誤頁面。錯誤頁面所需的資源要比一個能夠響應合法訪問的在線網站少得多。</p><h3 id="在-ubuntu-16-04-上安裝-mod-evasive" tabindex="-1">在 Ubuntu 16.04 上安裝 mod_evasive <a class="header-anchor" href="#在-ubuntu-16-04-上安裝-mod-evasive" aria-label="Permalink to “在 Ubuntu 16.04 上安裝 mod_evasive”">​</a></h3><p>Ubuntu 16.04 默認的軟件庫中包含了 mod_evasive，名稱為 “libapache2-mod-evasive”。您可以使用 <code>apt-get</code> 來完成安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get update</span></span>
<span class="line"><span>apt-get upgrade</span></span>
<span class="line"><span>apt-get install libapache2-mod-evasive</span></span></code></pre></div><p>現在我們需要配置 mod_evasive。</p><p>它的配置文件位於 <code>/etc/apache2/mods-available/evasive.conf</code>。默認情況下，所有模組的設置在安裝後都會被註釋掉。因此，在修改配置文件之前，模組不會干擾到網站流量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;IfModule mod_evasive20.c&gt;</span></span>
<span class="line"><span>   #DOSHashTableSize    3097</span></span>
<span class="line"><span>   #DOSPageCount        2</span></span>
<span class="line"><span>   #DOSSiteCount        50</span></span>
<span class="line"><span>   #DOSPageInterval     1</span></span>
<span class="line"><span>   #DOSSiteInterval     1</span></span>
<span class="line"><span>   #DOSBlockingPeriod   10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   #DOSEmailNotify      you@yourdomain.com</span></span>
<span class="line"><span>   #DOSSystemCommand    &quot;su - someuser -c &#39;/sbin/... %s ...&#39;&quot;</span></span>
<span class="line"><span>   #DOSLogDir           &quot;/var/log/mod_evasive&quot;</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><p>第一部分的參數的含義如下：</p><ul><li><code>DOSHashTableSize</code> - 正在訪問網站的 IP 地址列表及其請求數的當前列表。</li><li><code>DOSPageCount</code> - 在一定的時間間隔內，每個頁面的請求次數。時間間隔由 DOSPageInterval 定義。</li><li><code>DOSPageInterval</code> - mod_evasive 統計頁面請求次數的時間間隔。</li><li><code>DOSSiteCount</code> - 與 <code>DOSPageCount</code> 相同，但統計的是來自相同 IP 地址對網站內任何頁面的請求數量。</li><li><code>DOSSiteInterval</code> - mod_evasive 統計網站請求次數的時間間隔。</li><li><code>DOSBlockingPeriod</code> - 某個 IP 地址被加入黑名單的時長（以秒為單位）。</li></ul><p>如果使用上面顯示的默認配置，則在如下情況下，一個 IP 地址會被加入黑名單：</p><ul><li>每秒請求同一頁面超過兩次。</li><li>每秒請求 50 個以上不同頁面。</li></ul><p>如果某個 IP 地址超過了這些閾值，則被加入黑名單 10 秒鐘。</p><p>這看起來可能不算久，但是，mod_evasive 將一直監視頁面請求，包括在黑名單中的 IP 地址，並重置其加入黑名單的起始時間。只要一個 IP 地址一直嘗試使用 DOS 攻擊該網站，它將始終在黑名單中。</p><p>其餘的參數是：</p><ul><li><code>DOSEmailNotify</code> - 用於接收 DOS 攻擊信息和 IP 地址黑名單的電子郵件地址。</li><li><code>DOSSystemCommand</code> - 檢測到 DOS 攻擊時運行的命令。</li><li><code>DOSLogDir</code> - 用於存放 mod_evasive 的臨時文件的目錄。</li></ul><h3 id="配置-mod-evasive" tabindex="-1">配置 mod_evasive <a class="header-anchor" href="#配置-mod-evasive" aria-label="Permalink to “配置 mod_evasive”">​</a></h3><p>默認的配置是一個很好的開始，因為它不會阻塞任何合法的用户。取消配置文件中的所有參數（<code>DOSSystemCommand</code> 除外）的註釋，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;IfModule mod_evasive20.c&gt;</span></span>
<span class="line"><span>   DOSHashTableSize   3097</span></span>
<span class="line"><span>   DOSPageCount       2</span></span>
<span class="line"><span>   DOSSiteCount       50</span></span>
<span class="line"><span>   DOSPageInterval    1</span></span>
<span class="line"><span>   DOSSiteInterval    1</span></span>
<span class="line"><span>   DOSBlockingPeriod  10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   DOSEmailNotify       JohnW@example.com</span></span>
<span class="line"><span>   #DOSSystemCommand    &quot;su - someuser -c &#39;/sbin/... %s ...&#39;&quot;</span></span>
<span class="line"><span>   DOSLogDir            &quot;/var/log/mod_evasive&quot;</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><p>必須要創建日誌目錄並且要賦予其與 apache 進程相同的所有者。這裏創建的目錄是 <code>/var/log/mod_evasive</code> ，並且在 Ubuntu 上將該目錄的所有者和組設置為 <code>www-data</code> ，與 Apache 服務器相同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir /var/log/mod_evasive</span></span>
<span class="line"><span>chown www-data:www-data /var/log/mod_evasive</span></span></code></pre></div><p>在編輯了 Apache 的配置之後，特別是在正在運行的網站上，在重新啓動或重新加載之前，最好檢查一下語法，因為語法錯誤將影響 Apache 的啓動從而使網站宕機。</p><p>Apache 包含一個輔助命令，是一個配置語法檢查器。只需運行以下命令來檢查您的語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apachectl configtest</span></span></code></pre></div><p>如果您的配置是正確的，會得到如下結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Syntax OK</span></span></code></pre></div><p>但是，如果出現問題，您會被告知在哪部分發生了什麼錯誤，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AH00526: Syntax error on line 6 of /etc/apache2/mods-enabled/evasive.conf:</span></span>
<span class="line"><span>DOSSiteInterval takes one argument, Set site interval</span></span>
<span class="line"><span>Action &#39;configtest&#39; failed.</span></span>
<span class="line"><span>The Apache error log may have more information.</span></span></code></pre></div><p>如果您的配置通過了 configtest 的測試，那麼這個模組可以安全地被啓用並且 Apache 可以重新加載：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a2enmod evasive</span></span>
<span class="line"><span>systemctl reload apache2.service</span></span></code></pre></div><p>mod_evasive 現在已配置好並正在運行了。</p><h3 id="測試" tabindex="-1">測試 <a class="header-anchor" href="#測試" aria-label="Permalink to “測試”">​</a></h3><p>為了測試 mod_evasive，我們只需要向服務器提出足夠的網頁訪問請求，以使其超出閾值，並記錄來自 Apache 的響應代碼。</p><p>一個正常併成功的頁面請求將收到如下響應：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 200 OK</span></span></code></pre></div><p>但是，被 mod_evasive 拒絕的將返回以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 403 Forbidden</span></span></code></pre></div><p>以下腳本會盡可能迅速地向本地主機（127.0.0.1，localhost）的 80 端口發送 HTTP 請求，並打印出每個請求的響應代碼。</p><p>你所要做的就是把下面的 bash 腳本複製到一個文件中，例如 <code>mod_evasive_test.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>set -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for i in {1..50}; do</span></span>
<span class="line"><span>        curl -s -I 127.0.0.1 | head -n 1</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>這個腳本的部分含義如下：</p><ul><li><code>curl</code> - 這是一個發出網絡請求的命令。 <ul><li><code>-s</code> - 隱藏進度表。</li><li><code>-I</code> - 僅顯示響應頭部信息。</li></ul></li><li><code>head</code> - 打印文件的第一部分。 <ul><li><code>-n 1</code> - 只顯示第一行。</li></ul></li></ul><p>然後賦予其執行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod 755 mod_evasive_test.sh</span></span></code></pre></div><p>在啓用 mod_evasive <strong>之前</strong>，腳本運行時，將會看到 50 行 “HTTP / 1.1 200 OK” 的返回值。</p><p>但是，啓用 mod_evasive 後，您將看到以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>前兩個請求被允許，但是在同一秒內第三個請求發出時，mod_evasive 拒絕了任何進一步的請求。您還將收到一封電子郵件（郵件地址在選項 <code>DOSEmailNotify</code> 中設置），通知您有 DOS 攻擊被檢測到。</p><p>mod_evasive 現在已經在保護您的網站啦！</p><hr>`,50)),p("p",null,[s[11]||(s[11]=a("via: ",-1)),i(e,{href:"https://bash-prompt.net/guides/mod_proxy/"},{default:n(()=>[...s[10]||(s[10]=[a("https://bash-prompt.net/guides/mod_proxy/",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("作者：",-1)),i(e,{href:"https://bash-prompt.net/about/"},{default:n(()=>[...s[12]||(s[12]=[a("Elliot Cooper",-1)])]),_:1}),s[16]||(s[16]=a(" 譯者：",-1)),i(e,{href:"https://github.com/jessie-pang"},{default:n(()=>[...s[13]||(s[13]=[a("jessie-pang",-1)])]),_:1}),s[17]||(s[17]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[19]||(s[19]=[a("Linux中國",-1)])]),_:1}),s[22]||(s[22]=a(" 榮譽推出",-1))])])}const y=t(h,[["render",c]]);export{S as __pageData,y as default};
